def multiple_to_single(L):
    """Write a function to convert a list of multiple integers into a single integer."""
    numbers = list(L)
    if not numbers:
        return 0
    sign = -1 if numbers[0] < 0 else 1
    digits = "".join(str(abs(number)) for number in numbers)
    return sign * int(digits)
